<script setup lang="ts">
import type { MeResponse, BillingHistoryResponse, BillingHistoryData } from '~~/server/types/api'
const { data: me, error: accountError, refresh: refreshAccount } = await useFetch<MeResponse>('/api/me', { server: false })
const { data: history, error: historyError, refresh: refreshHistory } = await useFetch<BillingHistoryResponse>('/api/billing/history', { server: false })
const records = computed(() => history.value?.success && 'paymentHistory' in history.value.data && 'creditActivity' in history.value.data ? history.value.data as BillingHistoryData : null)
const money = (amount: number, currency: string) => new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(amount / 100)
const date = (value: string) => new Date(value).toLocaleDateString()
</script>
<template><section class="card"><h2>Available credits</h2><p v-if="me?.success" class="price">{{ me.data.credits }}</p><p v-else-if="accountError" class="error">Couldn’t load your balance.</p><p v-else>Loading…</p><UButton variant="outline" @click="() => { refreshAccount(); refreshHistory() }">Refresh</UButton></section><section class="card mt-6"><h2>Recent payments</h2><p v-if="historyError" class="error">Couldn’t load your payment history.</p><template v-else-if="records"><div v-if="records.paymentHistory.length" class="table-wrap"><table><thead><tr><th>Product</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody><tr v-for="(payment, index) in records.paymentHistory" :key="index"><td>{{ payment.product }}</td><td>{{ money(payment.amountCents, payment.currency) }}</td><td>{{ payment.status }}</td><td>{{ date(payment.date) }}</td></tr></tbody></table></div><p v-else>No purchases yet.</p><h2 class="mt-6">Recent credit activity</h2><p v-if="!records.creditActivity.length">No credit activity yet.</p><div v-else class="table-wrap"><table><thead><tr><th>Activity</th><th>Credits</th><th>Date</th></tr></thead><tbody><tr v-for="(item, index) in records.creditActivity" :key="index"><td>{{ item.activity }}</td><td>{{ item.change }}</td><td>{{ date(item.date) }}</td></tr></tbody></table></div></template><p v-else>Loading history…</p></section></template>
